% =========================================================================
% Phase 2b HW17: RAG Context Correlation (Context Depth vs Robustness Flips)
% =========================================================================
% 1. Load the core dataset
fileName = 'ISEF_Telemetry_Modeler_v4.xlsx';
sheetName = 'D1-D3';
warning('off', 'MATLAB:table:ModifiedAndSavedVarnames');
data = readtable(fileName, 'Sheet', sheetName);

% Clean any empty rows generated by Excel formatting
data(ismissing(data.Test_Phase), :) = [];

% 2. Isolate Unshielded Runs (12 Runs)
% We exclude ISEF runs to measure the natural degradation of the unshielded LLM
unshielded_idx = strcmp(data.Test_Phase, 'Baseline') | strcmp(data.Test_Phase, 'Adversarial');
baselineData = data(unshielded_idx, :);

% Extract RAG Context Depth (Total Tokens)
tokens = baselineData.Tokens;

% Create Binary Vector (1 = Robustness Flip, 0 = Safe Halt / Pass)
is_flip = contains(string(baselineData.Result), 'Robustness Flip');
flip_binary = double(is_flip);

% 3. Calculate Correlation Coefficient
[R, pValue] = corrcoef(tokens, flip_binary);
corr_coeff = R(1,2);
p_val = pValue(1,2);

% Construct the complete output string
outText = sprintf('=============================================================================\n');
outText = [outText, sprintf('                  PHASE 2: RAG CONTEXT DEPTH CORRELATION                     \n')];
outText = [outText, sprintf('=============================================================================\n')];
outText = [outText, sprintf('Sample Size (Unshielded Runs): %d\n', length(tokens))];
outText = [outText, sprintf('Total Robustness Flips:        %d\n', sum(flip_binary))];
outText = [outText, sprintf('Correlation Coefficient (r):   %.4f\n', corr_coeff)];
outText = [outText, sprintf('P-Value:                       %.4f\n', p_val)];
outText = [outText, sprintf('-----------------------------------------------------------------------------\n')];

% Display to the Command Window
fprintf(1, '%s', outText);

% 4. Generate Correlation Scatter Plot
fig_corr = figure('Name', 'RAG Context Depth vs. Robustness Flip', 'Position', [150, 150, 800, 500]);

% Plot the two states
scatter(tokens(flip_binary == 1), flip_binary(flip_binary == 1), 100, [0.8500 0.3250 0.0980], 'filled', 'MarkerEdgeColor', 'k', 'DisplayName', 'Robustness Flip (Failure)');
hold on;
scatter(tokens(flip_binary == 0), flip_binary(flip_binary == 0), 100, [0 0.4470 0.7410], 'filled', 'MarkerEdgeColor', 'k', 'DisplayName', 'Safe Halt / Pass');

% Fit a linear trendline to visually represent the correlation trajectory
p = polyfit(tokens, flip_binary, 1);
x_fit = linspace(min(tokens)*0.9, max(tokens)*1.1, 100);
y_fit = polyval(p, x_fit);
plot(x_fit, y_fit, '--k', 'LineWidth', 1.5, 'DisplayName', 'Correlation Trend');
hold off;

% 5. Formatting and Export
grid on;
ylim([-0.2, 1.2]);
yticks([0 1]);
yticklabels({'0 (No Flip)', '1 (Robustness Flip)'});
xlabel('RAG Context Depth (Total Tokens)', 'FontSize', 11, 'FontWeight', 'bold');
ylabel('Adversarial Subversion State', 'FontSize', 11, 'FontWeight', 'bold');
title('Unshielded Baseline: Context Depth vs. Robustness Flips', 'FontSize', 13, 'Interpreter', 'none');
legend('Location', 'best');

% --- Auto-Save Section ---
outputDir = 'Chapter4_Graphics';
if ~exist(outputDir, 'dir')
    mkdir(outputDir);
end

pngFileName = fullfile(outputDir, 'RAG_Context_Correlation.png');
figFileName = fullfile(outputDir, 'RAG_Context_Correlation.fig');
txtFileName = fullfile(outputDir, 'RAG_Context_Correlation_Results.txt');

exportgraphics(fig_corr, pngFileName, 'Resolution', 300);
savefig(fig_corr, figFileName);

% Save text results
fid = fopen(txtFileName, 'w');
fprintf(fid, '%s', outText);
fclose(fid);

disp(['Correlation graphics (PNG and FIG) successfully saved to: ', outputDir]);
disp(['Statistical summary successfully saved to: ', txtFileName]);